INSERT INTO _seed_neuro_a1_context (unit_id,topic_id,actor_id) SELECT cu.id,COALESCE((SELECT id FROM quiz_topics WHERE curricular_unit_id=cu.id AND title='Aula 1 - Introdução ao estudo de Neuroanatomia' LIMIT 1),'quiz-topic-neuro-aula-1'),actor.id FROM curricular_units cu CROSS JOIN _seed_neuro_a1_actor actor WHERE cu.code='NEURO' AND cu.active=1;
INSERT INTO _seed_neuro_a1_context (unit_id,topic_id,actor_id) SELECT NULL,NULL,NULL WHERE NOT EXISTS (SELECT 1 FROM _seed_neuro_a1_context);
INSERT INTO quiz_topics (id,curricular_unit_id,title,description,status,sort_order,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT topic_id,unit_id,'Aula 1 - Introdução ao estudo de Neuroanatomia','Descrição geral do sistema nervoso central: encéfalo, espinal medula, organização funcional e sistema ventricular.','published',1,unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_a1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,title=excluded.title,description=excluded.description,status='published',published_at=COALESCE(quiz_topics.published_at,excluded.published_at),published_by=COALESCE(quiz_topics.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-a1-001',unit_id,topic_id,'Qual afirmação descreve corretamente a relação entre as estruturas assinaladas e os nervos que delas emergem?','/quiz-images/neuro/aula-1/page-004-figure-2.jpeg','Encéfalo e espinal medula constituem o sistema nervoso central. Os nervos cranianos e espinhais não pertencem a esse par estrutural: estabelecem a comunicação, respetivamente, do encéfalo e da espinal medula com a periferia.','easy','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_a1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=excluded.image_url,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-001-option-1','quiz-neuro-a1-001','O encéfalo e a espinal medula formam o sistema nervoso central; os nervos cranianos e espinhais ligam-no à periferia',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-001-option-2','quiz-neuro-a1-001','O encéfalo e os nervos cranianos formam o sistema nervoso central; a espinal medula pertence ao sistema nervoso periférico',2,0);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-001-option-3','quiz-neuro-a1-001','A espinal medula e os nervos espinhais formam o sistema nervoso central; o encéfalo funciona como órgão periférico',3,0);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-001-option-4','quiz-neuro-a1-001','Os nervos cranianos e espinhais formam o sistema nervoso central; o encéfalo e a espinal medula são órgãos efetores',4,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-a1-002',unit_id,topic_id,'No sistema nervoso central, o termo núcleo identifica:',NULL,'Um núcleo reúne corpos celulares neuronais do sistema nervoso central com uma função habitualmente comum. Um feixe organiza axónios, uma agregação periférica corresponde a um gânglio e uma camada superficial hemisférica corresponde ao córtex.','easy','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_a1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=excluded.image_url,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-002-option-1','quiz-neuro-a1-002','Feixe de axónios que partilham uma origem ou um destino',1,0);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-002-option-2','quiz-neuro-a1-002','Pequena agregação de corpos celulares neuronais que partilham habitualmente uma função',2,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-002-option-3','quiz-neuro-a1-002','Agregação periférica de corpos celulares associada a um nervo',3,0);
