INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-003-option-2','quiz-neuro-a1-003','Corpos celulares sensitivos reunidos apenas em gânglios periféricos',2,0);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-003-option-3','quiz-neuro-a1-003','Corpos celulares neuronais, dendrites e grande parte das interações sinápticas',3,1);
