INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-005-option-2','quiz-neuro-a1-005','Cada metade do corpo comunica obrigatoriamente apenas com o hemisfério do mesmo lado',2,0);
