INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-006-option-2','quiz-neuro-a1-006','Formam núcleos discretos no tronco cerebral e colunas mais contínuas na espinal medula',2,1);
