INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-025-option-2','quiz-neuro-a1-025','É um feixe motor no centro da substância branca',2,0);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-a1-025-option-3','quiz-neuro-a1-025','É a continuação intramedular do espaço epidural',3,0);
